from pathlib import Path
from html import escape
import argparse,json,re
from datetime import date as Date

ROOT=Path(__file__).resolve().parent
parser=argparse.ArgumentParser(description='Build Arthyra Studio static pages.')
parser.add_argument('--publish',action='store_true',help='Reject an unfinished contact address before publication.')
args=parser.parse_args()
config=json.loads((ROOT/'site.json').read_text(encoding='utf-8'))
updated=Date.fromisoformat(config['updated'])
months_tr=['Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık']
months_en=['January','February','March','April','May','June','July','August','September','October','November','December']
email=config.get('contact_email')
if email and not re.fullmatch(r'[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}',email):
    raise SystemExit('Invalid contact email')
if args.publish and not email:
    raise SystemExit('Publication stopped: a user-approved public contact email is required.')
draft='' if email else '<div class="draft" role="note">Yayın öncesi önizleme · İletişim adresi henüz belirlenmedi</div>'
contact=(f'<a href="mailto:{escape(email)}">{escape(email)}</a>' if email else '<span class="missing-contact">Destek e-postası yayın öncesinde eklenecek.</span>')
contact_en=(f'<a href="mailto:{escape(email)}">{escape(email)}</a>' if email else '<span class="missing-contact">A public support email will be added before publication.</span>')

base=config['base_url'].rstrip('/')
if not re.fullmatch(r'https://[a-z0-9.-]+(/[A-Za-z0-9._-]+)*',base):
    raise SystemExit('Invalid base_url')
PAGES=['/','/gunebirsoz/gizlilik/','/gunebirsoz/privacy/','/gunebirsoz/kaynaklar/']
POLICY_ALTERNATES=[('tr','/gunebirsoz/gizlilik/'),('en','/gunebirsoz/privacy/'),('x-default','/gunebirsoz/gizlilik/')]

def seo(title,description,lang,path,alternates=()):
    # Absolute URLs come from site.json base_url; page links stay relative so local preview works.
    url=base+path
    links=''.join(f'<link rel="alternate" hreflang="{code}" href="{base}{alt}">' for code,alt in alternates)
    return (f'<link rel="canonical" href="{url}">{links}<meta property="og:type" content="website"><meta property="og:site_name" content="Arthyra Studio">'
            f'<meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(description)}"><meta property="og:url" content="{url}">'
            f'<meta property="og:image" content="{base}/assets/og-image.jpg"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630">'
            f'<meta property="og:image:alt" content="Arthyra Studio"><meta property="og:locale" content="{"en_US" if lang=="en" else "tr_TR"}"><meta name="twitter:card" content="summary_large_image">')

def head(title,description,prefix='',lang='tr',extra=''):
    return f"""<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(description)}"><meta name="theme-color" content="#222724"><link rel="icon" type="image/png" href="{prefix}assets/arthyra-icon.png"><link rel="stylesheet" href="{prefix}assets/site.css">{extra}</head><body>{draft}<a class="skip" href="#main">{'Skip to content' if lang=='en' else 'İçeriğe geç'}</a>"""

def brand(prefix=''):
    return f'<a class="brand" href="{prefix or "./"}" aria-label="Arthyra Studio"><img src="{prefix}assets/arthyra-icon.png" width="43" height="43" alt="">Arthyra <span>Studio</span></a>'

def footer(prefix='',lang='tr'):
    label='Privacy' if lang=='en' else 'Gizlilik'
    path='privacy' if lang=='en' else 'gizlilik'
    return f'<div class="dark"><footer class="wrap footer"><span>© 2026 Arthyra Studio</span><a href="{prefix}gunebirsoz/{path}/">Güne Bir Söz · {label}</a></footer></div></body></html>'

home_title,home_desc='Arthyra Studio — Uygulamalar ve oyunlar','Arthyra Studio’nun projeleri: günlük alıntı uygulaması Güne Bir Söz ve sıra tabanlı kart oyunu Osmanlı Seferi.'
home=head(home_title,home_desc,extra=seo(home_title,home_desc,'tr','/'))+f"""
<div class="dark"><header class="wrap header">{brand()}<nav class="nav" aria-label="Ana menü"><a href="#uygulamalar">Projeler</a><a href="gunebirsoz/gizlilik/">Gizlilik</a><a href="#iletisim">İletişim</a></nav></header></div>
<main id="main"><div class="dark"><section class="wrap hero"><div><p class="eyebrow">Bağımsız uygulama stüdyosu</p><h1>İyi fikirler,<br><em>gündelik hayatın</em><br>içinde.</h1><p class="intro">Ücretsiz uygulamalar ve oyunlar geliştiriyoruz. Sade, özenli ve kullanması keyifli deneyimler için.</p><a class="arrowlink" href="#uygulamalar">Projelerimizi keşfedin <span aria-hidden="true">↘</span></a></div><div class="hero-mark" aria-hidden="true"><img src="assets/arthyra-icon.png" width="512" height="512" alt=""></div></section></div>
<section class="wrap section" id="uygulamalar"><div class="section-head"><div><p class="eyebrow">Projelerimiz</p><h2>Uygulamalar ve oyunlar</h2></div><p>Günlük alıntılar için Güne Bir Söz, sıra tabanlı kart savaşları için Osmanlı Seferi.</p></div>
<article class="app"><div><div class="app-header"><img src="assets/gunebirsoz-icon.png" width="72" height="72" alt="Güne Bir Söz simgesi"><div><h3>Güne Bir Söz</h3><p>Ücretsiz · Android · Google Play yayını hazırlanıyor</p></div></div><p>Günün alıntısını oku, sevdiklerini sakla ve hatırlatma saatini kendin seç. Cihazındaki koleksiyon internetsiz de yanında; bağlantı olduğunda Türkçe Vikisöz’den derlediğimiz kataloğu yenileyebilirsin.</p><ul class="features"><li>Günlük alıntılar</li><li>Favori koleksiyonu</li><li>Yerel hatırlatmalar</li><li>Ana ekran widget’ı</li></ul><a class="button" href="gunebirsoz/gizlilik/">Gizlilik politikasını okuyun</a></div><div class="quote-sample"><p class="small">Bir alıntı, kısa bir mola</p><blockquote>“Sevelim sevilelim<br>Dünya kimseye kalmaz.”</blockquote><cite>Yunus Emre</cite><p class="quote-caption">Uygulamadaki başlangıç koleksiyonundan bir örnek.</p></div></article>
<article class="app game" id="osmanli-seferi" aria-labelledby="osmanli-seferi-baslik">
  <div>
    <div class="app-header"><div><h3 id="osmanli-seferi-baslik">Osmanlı Seferi</h3><p>Mobil strateji oyunu · Geliştirme aşamasında</p></div></div>
    <p>Ordunu seç ve hamleni planla. Osmanlı temalı bu sıra tabanlı kart oyununda, doğru kartı doğru anda oynamak savaşın gidişatını değiştirir.</p>
    <ul class="features"><li>Sıra tabanlı kart savaşları</li><li>Tek oyunculu sefer</li><li>Aynı cihazda iki oyuncu</li><li>Farklı ordu seçenekleri</li></ul>
  </div>
  <div class="game-art" aria-hidden="true"><span class="game-art-label">Arthyra Studio · Oyun</span><span class="game-art-title">Osmanlı<br>Seferi</span><span class="game-art-label">Sıra tabanlı kart savaşı</span></div>
</article></section>
<section class="wrap section" id="yaklasim"><p class="eyebrow">Yaklaşımımız</p><div class="principles"><div><span class="number">01 / ERİŞİLEBİLİR</span><h3>Herkes için ücretsiz.</h3><p>Uygulamalarımızı ücretsiz sunuyoruz. İyi bir deneyime ulaşmak kolay olsun istiyoruz.</p></div><div><span class="number">02 / SADE</span><h3>İşe yarayan ayrıntılar.</h3><p>Güne Bir Söz’de favorilerini saklayabilir, bildirim saatini seçebilir ve alıntıları paylaşabilirsin.</p></div><div><span class="number">03 / ŞEFFAF</span><h3>Ne yaptığımız açık.</h3><p>Her uygulamanın veri kullanımını kendi gizlilik sayfasında anlatıyoruz. Bilgiler doğrudan okunabilir, giriş gerekmez.</p></div></div></section>
<section class="wrap contact" id="iletisim"><div><p class="eyebrow">İletişim</p><h2>Bir fikrin veya sorun mu var?</h2><p>Uygulamalar ve gizlilik konuları için bize ulaşabilirsin.</p></div><div class="contact-address">{contact}</div></section></main>
"""+footer()
(ROOT/'docs/index.html').write_text(home,encoding='utf-8')

tr=[
('kapsam','1. Kapsam ve yayıncı', """<p>Bu politika, Arthyra Studio tarafından geliştirilen <strong>Güne Bir Söz</strong> Android uygulamasının veri kullanımını açıklar. Uygulama günlük alıntılar, favoriler, isteğe bağlı yerel bildirimler, ana ekran widget’ı ve paylaşım özellikleri sunar.</p><p>Uygulama içinde hesap oluşturulmaz; ad, telefon veya e-posta girilmesi istenmez. Uygulama reklam veya kullanıcı davranışını izleyen analitik araçları kullanmaz. Bu açıklama 1.1.1 ve 1.1.2 sürümlerinin özelliklerine göre hazırlanmıştır; sürümler arasındaki fark ilgili bölümde belirtilir.</p>"""),
('yerel','2. Cihazda saklanan bilgiler', """<p>Şu bilgiler uygulamanın cihazınızdaki depolama alanında tutulur:</p><ul><li>Favorilere eklediğiniz alıntıların kimlikleri.</li><li>Bildirimlerin açık/kapalı durumu ve seçtiğiniz saat.</li><li>Çevrimdışı okumak için alıntı koleksiyonu ve kaynak bilgileri.</li><li>Günün alıntısının tutarlı kalması için yapılan günlük seçimler.</li><li>1.1.2 ve sonrasında: günlük alıntıların size özgü bir sırayla gelmesi için cihazda rastgele üretilen bir sıra bilgisi. Bu bilgi cihazdan gönderilmez ve sizi tanımlamak için kullanılmaz.</li></ul><p>Bu kayıtları Arthyra Studio’ya ait bir kullanıcı sunucusuna yüklemiyoruz. Widget, gösterilecek alıntıları cihazdaki uygulamadan alır.</p>"""),
('internet','3. İnternet bağlantısı ve üçüncü taraflar', """<p>Uygulama açılışta, ön plana döndüğünde veya koleksiyonu elle yenilediğinizde alıntı koleksiyonunu indirir. Otomatik yenilemeler arasında en az 6 saat bulunur. <strong>1.1.2 ve sonrasında</strong> koleksiyon, Arthyra Studio’nun bu web sitesinden (<code>arthyrastudio.info</code>) tek bir dosya olarak indirilir. Bu dosyayı <a href="https://tr.wikiquote.org/">Türkçe Vikisöz</a>’den kaynaklı sözleri seçerek biz hazırlarız. <strong>1.1.1 ve öncesinde</strong> uygulama alıntı sayfalarını doğrudan Türkçe Vikisöz API’sinden ister.</p><p>İsteklere yalnızca uygulamanın adını ve sürümünü içeren bir tarayıcı kimliği eklenir. Favorileriniz, bildirim ayarlarınız veya cihazınıza özgü bir kimlik gönderilmez. Her internet bağlantısında olduğu gibi, isteği karşılayan hizmet bağlantıyı sağlamak için IP adresinizi ve isteğe ilişkin teknik bilgileri görebilir. Bu, 1.1.2’de web sitemizi sunan GitHub’dır (bkz. bölüm 9), 1.1.1’de Wikimedia’dır (<a href="https://foundation.wikimedia.org/wiki/Policy:Privacy_policy">Wikimedia gizlilik politikası</a>). Bir alıntının kaynak bağlantısını açarsanız tarayıcınız Vikisöz’e bağlanır.</p><p>Google Play’den indirme ve güncelleme gibi platform işlemleri Google’ın kendi koşullarına ve gizlilik politikasına tabidir.</p>"""),
('bildirim','4. Bildirimler ve izinler', """<p>Hatırlatmalar Android’in yerel bildirim sistemiyle cihazda planlanır. Uygulama uzaktan push bildirim hizmeti için kayıt oluşturmaz ve bildirim göndermek amacıyla bir push token talep etmez.</p><p>Bildirim gösterme izni ve desteklenen cihazlarda tam zamanlı alarm izni, seçtiğiniz saatte hatırlatma sunmak için kullanılır. Bildirimleri uygulama veya Android ayarlarından kapatabilirsiniz.</p>"""),
('paylasim','5. Paylaşım ve oluşturulan görseller', """<p>Paylaşımı siz başlattığınızda seçtiğiniz alıntı metni veya alıntıdan üretilen hikâye görseli Android’in paylaşım menüsüne aktarılır. Hangi uygulama veya alıcıyla paylaşılacağını siz seçersiniz; otomatik paylaşım yapılmaz.</p><p>Hikâye görseli cihazda üretilir ve uygulamanın geçici dosya alanında tutulabilir. Arthyra Studio’ya otomatik yüklenmez. Paylaşmayı seçtiğiniz uygulama veya hizmet, içeriği kendi gizlilik koşullarına göre işleyebilir.</p>"""),
('saklama','6. Saklama, silme ve cihaz yedekleri', """<p>Favori ve tercih kayıtları siz uygulama verilerini temizleyene veya uygulamayı kaldırana kadar cihazda kalabilir. Bir favoriyi uygulama içinden kaldırabilirsiniz. Tüm yerel kayıtları silmek için Android’de uygulamanın depolama/veri temizleme seçeneklerini kullanabilirsiniz. Bu işlem favorileri, tercihleri ve indirilen koleksiyonu sıfırlar.</p><p><strong>Cihaz yedekleri:</strong> Android sürümüne, cihazınıza ve yedekleme ayarlarınıza bağlı olarak uygulama verilerinizin bir kopyası sistem yedeklemesine dahil edilebilir ve yeniden kurulumda geri gelebilir. Arthyra Studio bu sistem yedeklerini işletmez. Yedekleri Android veya yedekleme sağlayıcınızın ayarlarından yönetebilirsiniz. <a href="https://support.google.com/android/answer/2819582?hl=tr">Android yedekleme bilgileri</a>.</p><p>Geçici paylaşım görselleri cihazın önbellek yönetimi veya uygulama verilerinin temizlenmesiyle kaldırılabilir. Uygulamada kapatılacak bir kullanıcı hesabı bulunmaz.</p>"""),
('guvenlik','7. Güvenlik ve kullanım sınırları', """<p>Çevrimiçi alıntı istekleri HTTPS üzerinden yapılır. Yerel kayıtlar cihazdaki uygulama depolama alanında saklanır. Cihazın kilidi, güncelliği, işletim sistemi izinleri ve seçtiğiniz yedekleme hizmeti bu kayıtların güvenliğini de etkiler.</p><p>Uygulama kişilerinize, mikrofonunuza, kameranıza veya hassas konumunuza dayalı bir özellik sunmaz. Verilerinizi reklam hedeflemesi için kullanmıyoruz veya satmıyoruz.</p>"""),
('cocuklar','8. Çocukların gizliliği', """<p>Uygulama kullanıcıdan yaş veya doğum tarihi istemez. Çocukların kişisel bilgilerini talep etmeyiz. Bir çocuğun bizimle iletişim sırasında kişisel bilgi paylaştığını düşünüyorsanız aşağıdaki iletişim adresinden ulaşabilirsiniz.</p>"""),
('site','9. Bu web sitesi ve değişiklikler', """<p>Bu sayfada reklam, ziyaretçi analitiği veya bizim eklediğimiz izleme çerezleri kullanılmaz. Sayfa GitHub Pages üzerinde sunulur; GitHub erişim isteklerine ilişkin teknik bilgileri kendi hizmet koşulları kapsamında işleyebilir. <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub gizlilik açıklaması</a>.</p><p>Uygulamanın özellikleri veya veri kullanımı değişirse bu politika da güncellenir. Güncel metin ve son güncelleme tarihi bu sayfada yayımlanır.</p>"""),
('iletisim','10. İletişim', f"""<p>Uygulama ve gizlilik sorularınız için yayıncı: <strong>Arthyra Studio</strong>.</p><p>{contact}</p><p>Bu adrese yazmayı seçerseniz e-posta adresinizi ve mesaj içeriğini talebinizi yanıtlamak için işleriz. Mesajlar talebin takibi ve gerekli kayıtların tutulması amacıyla, ihtiyaç duyulan süre boyunca saklanabilir; uygulamanın favori ve bildirim verileri mesajınıza otomatik eklenmez.</p>""")]

en=[
('scope','1. Scope and publisher', '<p>This policy explains data handling in <strong>Güne Bir Söz</strong>, the Android app published by <strong>Arthyra Studio</strong>. The app provides daily quotations, favorites, optional local reminders, a home screen widget and sharing.</p><p>The app does not require an account or ask you to enter a name, phone number or email address. It does not use advertisements or behavioral analytics tools. This description reflects versions 1.1.1 and 1.1.2; differences are noted where they apply.</p>'),
('local','2. Information stored on your device', '<p>The app stores favorite quotation identifiers, reminder preferences and time, downloaded quotations and source information, selected daily quotations and, from version 1.1.2, a randomly generated ordering value that gives you your own sequence of daily quotations, in its local app storage. The ordering value is not sent from the device and is not used to identify you. Daily selections keep the same quotation consistent across the app, reminders and widget.</p><p>These records are not uploaded to an Arthyra Studio user server. The widget receives the quotations it displays from the app on your device.</p>'),
('internet','3. Internet connections and third parties', '<p>At startup, on returning to the foreground, or when you manually refresh the collection, the app downloads the quotation collection; automatic refreshes are at least 6 hours apart. <strong>From version 1.1.2</strong> the collection is a single file downloaded from this Arthyra Studio website (<code>arthyrastudio.info</code>), which we compile from sourced quotations on <a href="https://tr.wikiquote.org/">Turkish Wikiquote</a>. <strong>Version 1.1.1 and earlier</strong> request author pages directly from the Turkish Wikiquote API.</p><p>Requests carry only a user agent with the app name and version. Your favorites, reminder preferences and any device-specific identifier are not included. As with any internet connection, the service answering the request can receive your IP address and technical request information: GitHub, which hosts this website (see section 9), for 1.1.2, and Wikimedia for 1.1.1 (<a href="https://foundation.wikimedia.org/wiki/Policy:Privacy_policy">Wikimedia Privacy Policy</a>). Opening a quotation’s source link connects your browser to Wikiquote.</p><p>Downloading and updating the app through Google Play are platform activities governed by Google’s own terms and privacy policy.</p>'),
('notifications','4. Reminders and permissions', '<p>Reminders are scheduled on your device using Android’s local notification system. The app does not register you for a remote push notification service or request a push token to send these reminders.</p><p>The notification permission, and exact alarm permission where supported, are used to provide reminders at your chosen time. You can disable notifications in the app or Android settings.</p>'),
('sharing','5. Sharing and generated images', '<p>When you choose to share, the selected quotation text or an image generated from it is passed to the Android share sheet. You select the destination app or recipient. The app does not share automatically.</p><p>Story images are created on your device and may be kept in temporary app files. They are not automatically uploaded to Arthyra Studio. A destination app or service you select may process the shared content under its own privacy policy.</p>'),
('retention','6. Retention, deletion and device backups', '<p>Favorites and preferences may remain on your device until you clear app data or uninstall the app. You can remove an individual favorite within the app. Android’s app storage/data clearing options reset favorites, preferences and downloaded quotations.</p><p><strong>System backups:</strong> Depending on your Android version, device and backup settings, copies of app data may be included in system backups and restored after reinstallation. Arthyra Studio does not operate these backups. Manage them through Android or your backup provider’s settings. <a href="https://support.google.com/android/answer/2819582?hl=en">Android backup information</a>.</p><p>Temporary sharing images may be removed by cache management or clearing app data. There is no in-app user account to close.</p>'),
('security','7. Security and limits', '<p>Online quotation requests use HTTPS. Local records are stored in the app storage area on your device. Your device lock, software updates, operating system permissions and chosen backup service also affect their security.</p><p>The app does not offer features based on contacts, microphone, camera or precise location access. We do not use your data for ad targeting or sell it.</p>'),
('children','8. Children’s privacy', '<p>The app does not ask for your age or date of birth. We do not request children’s personal information. If you believe a child has shared personal information with us through a support message, please contact us below.</p>'),
('website','9. This website and policy updates', '<p>This website does not include advertisements, visitor analytics or tracking cookies added by us. It is hosted on GitHub Pages; GitHub may process technical request information under its own service terms. See the <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub General Privacy Statement</a>.</p><p>We update this policy when app features or data handling changes. The current policy and its last updated date are published on this page.</p>'),
('contact','10. Contact',f'<p>Publisher for app and privacy questions: <strong>Arthyra Studio</strong>.</p><p>{contact_en}</p><p>If you choose to email us, we process your email address and message to answer your request. Messages may be kept for as long as needed to handle the request and retain necessary records. Your app favorites and reminder data are not attached automatically.</p>')]

for lang,slug,sections in [('tr','gizlilik',tr),('en','privacy',en)]:
    title='Gizlilik Politikası' if lang=='tr' else 'Privacy Policy'
